import numpy as np
import time


def _C(h):
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0 or not np.all(np.isfinite(h)):
        return np.inf
    if np.any(h < 0) or not h.any():
        return np.inf
    conv = np.convolve(h, h)
    return 2.0 * h.size * np.max(conv) / (np.sum(h) ** 2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    best = None
    best_c = np.inf

    def consider(h):
        nonlocal best, best_c
        h = np.asarray(h, dtype=float)
        if h.size > 30000 or h.size < 1:
            return
        c = _C(h)
        if c < best_c:
            best_c = c
            best = h.copy()

    # Candidate starting points
    if start is not None:
        consider(start)

    # A good analytic-ish shape: smooth bump (raised cosine-like) sampled finely.
    for N in (50, 100, 200, 400, 800):
        x = (np.arange(N) + 0.5) / N * 2.0 - 1.0  # in (-1,1)
        # try a few shapes
        for p in (0.5, 1.0, 2.0):
            h = np.maximum(0.0, (1.0 - x * x)) ** p
            consider(h)
        h = np.cos(np.pi * x / 2.0) ** 2
        consider(h)

    # Local refinement: coordinate-wise multiplicative perturbations.
    rng = np.random.default_rng(12345)

    def refine(h, rounds, scale):
        nonlocal best, best_c
        h = np.asarray(h, dtype=float)
        c = _C(h)
        n = h.size
        for _ in range(rounds):
            if time.process_time() > deadline:
                return
            improved = False
            # Try perturbing a random subset of coordinates
            idxs = rng.permutation(n)
            for i in idxs:
                if time.process_time() > deadline:
                    return
                old = h[i]
                for factor in (1.0 + scale, 1.0 - scale, 1.0 + 2*scale, 1.0 - 2*scale):
                    nh = old * factor
                    if nh < 0:
                        continue
                    h[i] = nh
                    nc = _C(h)
                    if nc < c - 1e-15:
                        c = nc
                        improved = True
                        break
                    else:
                        h[i] = old
                if c < best_c:
                    best_c = c
                    best = h.copy()
            if not improved:
                break

    # Refine the best found so far, plus a fine constant-ish start.
    if best is None:
        best = np.ones(50)
        best_c = _C(best)

    for scale in (0.5, 0.2, 0.05, 0.01):
        if time.process_time() > deadline:
            break
        refine(best, rounds=3, scale=scale)

    return best

