            return
        c = _C(h)
        if c < best_c:
            best_c = c
            best = h.copy()

    if start is not None:
        consider(start)

    # Multi-resolution polynomial-log shape fitting.
    # The optimal f is known to be a smooth bump; a quartic log-shape is a
    # rich family that captures the optimal profile well.
    Ns = [200, 400, 800, 1600]
    seeds = [
        (2.6, 0.0, 0.0, 0.0),
        (0.0, -10.0, 0.0, 0.0),
