import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)) or np.any(h < 0):
        return np.inf
    return 2.0 * h.size * np.max(np.convolve(h, h)) / (s * s)


def _resample(h, N):
    # Resample a height array onto N steps (piecewise-constant, area-preserving-ish).
    n = len(h)
    if n == N:
        return h.astype(float)
    idx = (np.arange(N) + 0.5) * n / N
    i0 = np.floor(idx).astype(int).clip(0, n - 1)
    i1 = (i0 + 1).clip(0, n - 1)
    w = idx - i0
    return (1 - w) * h[i0] + w * h[i1]


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    best = None
    best_c = np.inf

    def consider(h):
        nonlocal best, best_c
        h = np.asarray(h, dtype=float)
        if h.size < 1 or h.size > 30000:
            return
        c = _C(h)
        if c < best_c:
            best_c = c
            best = h.copy()

    if start is not None:
        consider(start)

    # Smooth parametric family: log-height as even polynomial in x (symmetric bump).
    def shape_even(x, params):
        z = np.zeros_like(x)
        for k, p in enumerate(params):
            z = z + p * x ** (2 * (k + 1))
        z = z - z.max()
        return np.exp(z)

    def shape_full(x, params):
        z = np.zeros_like(x)
        for k, p in enumerate(params):
            z = z + p * x ** (k + 1)
        z = z - z.max()
        return np.exp(z)

    # Even-family polynomial fit at several resolutions (optimal f is symmetric).
    Ns = [200, 400, 800, 1600, 3200]
    seeds_even = [
        (-40.0, 0.0),
        (-40.0, -300.0),
        (-30.0, -200.0, 0.0),
        (-25.0, -100.0, -500.0),
        (-20.0, 0.0, -400.0, 0.0),
    ]
    for N in Ns:
        if time.process_time() > deadline:
            break
        x = np.linspace(-0.25, 0.25, N, endpoint=False) + 0.25 / N

        def obj_even(p):
            return _C(shape_even(x, p))

        for p0 in seeds_even:
            if time.process_time() > deadline:
                break
            try:
                res = minimize(obj_even, np.array(p0, dtype=float),
                               method='Nelder-Mead',
                               options={'maxiter': 4000, 'xatol': 1e-10,
                                        'fatol': 1e-13})
                consider(shape_even(x, res.x))
            except Exception:
                pass

    # If we have a candidate, refine at high N via direct coordinate moves.
    if best is None:
        best = np.ones(100)
        best_c = _C(best)

    # Work at the best candidate's resolution; try a high-N version too.
    N_work = max(len(best), 2000)
    h = _resample(best, N_work)
    c = _C(h)

    rng = np.random.default_rng(12345)

    def coordinate_refine(h, c, scale, sweeps):
        n = h.size
        for _ in range(sweeps):
            if time.process_time() > deadline:
                return h, c
            improved = False
            order = rng.permutation(n)
            for i in order:
                if time.process_time() > deadline:
                    return h, c
                old = h[i]
                if old <= 0:
                    continue
                for factor in (1.0 + scale, 1.0 - scale):
                    h[i] = old * factor
                    nc = _C(h)
                    if nc < c - 1e-15:
                        c = nc
                        improved = True
                        break
                    h[i] = old
            if not improved:
                break
        return h, c

    for scale in (0.05, 0.02, 0.008, 0.003, 0.001):
        if time.process_time() > deadline:
            break
        h, c = coordinate_refine(h, c, scale, sweeps=4)
        consider(h)

    if best is None or best_c == np.inf:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(50)

    # Verify start not better
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.sum() > 0 and _C(s) <= best_c:
            return s

    print("even-poly + coord C = %.6f" % best_c)
    return best

