        return np.ones(50)

    # Coordinate refinement in log-space (multiplicative moves).
    def refine(h, rounds, scale):
        nonlocal best, best_c
        h = np.asarray(h, dtype=float).copy()
        c = _C(h)
        n = h.size
        rng = np.random.default_rng(7)
        for _ in range(rounds):
            if time.process_time() > deadline:
                return
            improved = False
            idxs = rng.permutation(n)
            for i in idxs:
                if time.process_time() > deadline:
                    return
                old = h[i]
                for factor in (1.0 + scale, 1.0 - scale):
                    nh = old * factor
                    if nh < 0:
                        continue
                    h[i] = nh
                    nc = _C(h)
                    if nc < c - 1e-14:
                        c = nc
                        improved = True
                        break
                    else:
                        h[i] = old
                if c < best_c:
                    best_c = c
                    best = h.copy()
            if not improved:
                break

    for scale in (0.05, 0.02, 0.005, 0.002):
        if time.process_time() > deadline:
            break
        refine(best, rounds=3, scale=scale)

    return best

