            if C < best_C:
                best_C = C
                best_f = f
        except Exception:
            pass
    if best_f is None:
        return np.ones(50)
    return best_f / best_f.max()


def _subgrad_descent(h0, lr_factor, t0, budget_seconds, max_iter=400):
    h = np.array(h0, dtype=float)
    h = np.maximum(h, 1e-12)
    N = len(h)
    logh = np.log(h)
    best_h = h.copy()
    best_C = _C(h)
    for it in range(max_iter):
        if time.process_time() - t0 > budget_seconds * 0.85:
            break
        h = np.exp(np.clip(logh, -20, 20))
        S = h.sum()
        if S <= 0:
            break
        conv = np.convolve(h, h)
        k = int(np.argmax(conv))
        C = 2.0 * N * conv[k] / (S * S)
        if C < best_C:
            best_C = C
            best_h = h.copy()
        g_h = np.full(N, -2.0 * C / S)
        i_lo = max(0, k - N + 1)
        i_hi = min(N - 1, k)
        if i_lo <= i_hi:
            idx = np.arange(i_lo, i_hi + 1)
            g_h[idx] += 4.0 * N * h[k - idx] / (S * S)
        g_log = h * g_h
        denom = np.max(np.abs(g_log)) + 1e-12
        g_log = g_log / denom
        lr = lr_factor * 0.05 / (1.0 + it / 50.0)
        logh = logh - lr * g_log
        logh = np.clip(logh, -20, 20)
        hh = np.exp(logh)
        m = hh.max()
        if m > 0:
            hh = hh / m
        logh = np.log(np.maximum(hh, 1e-12))
    h = np.exp(np.clip(logh, -20, 20))
    C = _C(h)
    if C < best_C:
        best_C = C
        best_h = h.copy()
    return best_h, best_C


