    if h0 is None:
        h0 = _make_fallback(400, t0, budget_seconds)

    start_C = _C(h0)
    best_h = h0.copy()
    best_C = start_C

    for N_target in (800, 1600, 3200):
        if time.process_time() - t0 > budget_seconds * 0.9:
            break
        h_init = _resample(h0, N_target)
        c_init = _C(h_init)
        if c_init < best_C:
            best_C = c_init
            best_h = h_init.copy()
        for lr_factor in (0.5, 1.0, 2.0):
