            if C < best_C:
                best_C = C
                best_h = h.copy()

    print("refine C = %.6f (start %.6f), N=%d" % (best_C, start_C, len(best_h)))
    return best_h

import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0 or not np.all(np.isfinite(h)) or np.any(h < 0):
        return np.inf
    return 2.0 * h.size * np.max(np.convolve(h, h)) / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.80
    rng = np.random.default_rng(12345)

    best = None
    best_c = np.inf

    def consider(h):
        nonlocal best, best_c
        h = np.asarray(h, dtype=float)
        if h.size < 1 or h.size > 30000:
            return
        if not np.all(np.isfinite(h)) or np.any(h < 0) or not h.any():
            return
        c = _C(h)
        if c < best_c:
            best_c = c
            best = h.copy()

    # Candidate continuous shape: exp of a polynomial in x, symmetric-ish.
    def make_shape(N, params):
        x = np.linspace(-0.25, 0.25, N, endpoint=False) + 0.25 / N
        z = np.zeros_like(x)
        for k, p in enumerate(params):
            if k == 0:
                z += p
            else:
                z += p * x ** k
        z = z - z.max()
        return np.exp(z)

    if start is not None:
        consider(start)

    # Fit a polynomial log-shape to start (or a default) to seed refinement.
    seeds = []
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.sum() > 0 and s.size >= 8:
            try:
                xs = np.linspace(-0.25, 0.25, s.size, endpoint=False) + 0.25 / s.size
                ls = np.log(np.maximum(s, 1e-9))
                coef = np.polyfit(xs, ls, 6)[::-1]  # ascending
                seeds.append(tuple(coef))
            except Exception:
                pass
    seeds.append((0.0, 0.0, -8.0, 0.0, -40.0, 0.0, 0.0))
    seeds.append((0.0, 2.5, -6.0, 0.0, -30.0, 0.0, 0.0))

    # Coarse multi-N polynomial fit.
    for N in (300, 600):
        if time.process_time() > deadline:
            break
        for p0 in seeds:
            if time.process_time() > deadline:
                break

            def obj(p, N=N):
                return _C(make_shape(N, p))

            try:
                res = minimize(obj, np.array(p0, dtype=float), method='Nelder-Mead',
                               options={'maxiter': 3000, 'xatol': 1e-9, 'fatol': 1e-13})
                consider(make_shape(N, res.x))
                consider(make_shape(1200, res.x))
            except Exception:
                pass

    if best is None:
        if start is not None:
            return np.asarray(start, dtype=float)
        return np.ones(50)

    # Take current best and resample to a working resolution.
    N = best.size
    # If start was small, upsample; if large, keep.
    if N < 400:
        N = 400
        xo = np.linspace(-0.25, 0.25, best.size, endpoint=False) + 0.25 / best.size
        xn = np.linspace(-0.25, 0.25, N, endpoint=False) + 0.25 / N
        h = np.exp(np.interp(xn, xo, np.log(np.maximum(best, 1e-9))))
    else:
        h = best.copy()

    # Coordinate-descent refinement in log-space with adaptive step.
    def refine(h, scale, max_steps):
        nonlocal best, best_c
        h = h.copy()
        c = _C(h)
        n = h.size
        for step in range(max_steps):
            if time.process_time() > deadline:
                return h, c
            improved = False
            order = rng.permutation(n)
            for i in order:
                old = h[i]
                if old <= 0:
                    continue
                for factor in (1.0 + scale, 1.0 / (1.0 + scale)):
                    h[i] = old * factor
                    nc = _C(h)
                    if nc < c - 1e-15:
                        c = nc
                        improved = True
                        break
                    else:
                        h[i] = old
            if c < best_c:
                best_c = c
                best = h.copy()
            if not improved:
                break
        return h, c

    for scale in (0.08, 0.03, 0.012, 0.005, 0.002):
        if time.process_time() > deadline:
            break
        h, _ = refine(h, scale, 20)

    return best

