def _poly_basis(x, deg):
    # scaled x in [-1,1] for conditioning
    return np.vander(x, deg + 1, increasing=True)


def construct(budget_seconds, start):
    t0 = time.process_time()

    if start is not None:
        h0 = np.asarray(start, dtype=float)
        if h0.sum() <= 0 or not np.all(np.isfinite(h0)):
            h0 = None
    else:
        h0 = None

    if h0 is None:
        h0 = _make_fallback(400, t0, budget_seconds)

    start_C = _C(h0)
    best_h = h0.copy()
    best_C = start_C

    # ---- Global search over degree-10 polynomial in log space ----
    DEG = 10
    N_search = 1600

    # Fit P to log(h0) at N_search resolution
    h_init = _resample(h0, N_search)
    h_init = np.maximum(h_init, 1e-12)
    x = np.linspace(-0.25, 0.25, N_search, endpoint=False) + 0.25 / N_search
    xs = x / 0.25  # in [-1,1)
    V = _poly_basis(xs, DEG)
    logh = np.log(h_init)
    try:
        coef0, *_ = np.linalg.lstsq(V, logh, rcond=None)
    except Exception:
        coef0 = np.zeros(DEG + 1)

    def make_h_from_coef(coef, N):
        xx = np.linspace(-0.25, 0.25, N, endpoint=False) + 0.25 / N
        xss = xx / 0.25
        VV = _poly_basis(xss, DEG)
        z = VV @ coef
        z = z - z.max()
        return np.exp(z)

    def obj_coef(coef):
        h = make_h_from_coef(coef, N_search)
        return _C(h)

    # Differential evolution
    bounds = [(-4.0, 4.0)] * (DEG + 1)
    best_coef = coef0.copy()
    best_coef_C = obj_coef(coef0)
    try:
        res = differential_evolution(
            obj_coef, bounds, popsize=15, maxiter=200, tol=1e-8,
            polish=False, seed=12345,
            init='sobol' if False else 'latinhypercube',
            workers=1, updating='immediate',
        )
        if res.fun < best_coef_C:
            best_coef_C = res.fun
            best_coef = res.x.copy()
    except Exception:
        pass

