    if C_poly < best_C:
        best_C = C_poly
        best_h = h_poly.copy()

    # Also try local subgrad descent from the polynomial solution at several N
    for N_target in (1600, 3200):
        if time.process_time() - t0 > budget_seconds * 0.85:
            break
        h_p = make_h_from_coef(best_coef, N_target)
        c_p = _C(h_p)
        if c_p < best_C:
            best_C = c_p
            best_h = h_p.copy()
        for lr_factor in (0.5, 1.0, 2.0):
