def _lbfgs_log(h_init, t0, budget_seconds, maxiter=3000):
    N = len(h_init)
    h_init = np.maximum(np.asarray(h_init, dtype=float), 1e-12)
    h_init = h_init / h_init.max()
    y0 = np.log(h_init)
    y0 = y0 - y0.max()

    def fg(y):
        y = y - y.max()
        h = np.exp(np.clip(y, -30, 30))
        S = h.sum()
        if S <= 0:
