        conv = np.convolve(h, h)
        k = int(np.argmax(conv))
        C = 2.0 * N * conv[k] / (S * S)
        g_h = np.full(N, -2.0 * C / S)
        i_lo = max(0, k - N + 1)
        i_hi = min(N - 1, k)
        if i_lo <= i_hi:
