                       options={'maxiter': maxiter, 'ftol': 1e-15, 'gtol': 1e-12,
                                'maxls': 50})
        y = res.x
        C = fg(y)[0]
        if C < best_C:
            best_C = C
            best_y = y.copy()
    except Exception:
        pass
    h = np.exp(np.clip(best_y - best_y.max(), -30, 30))
    return h, best_C


