import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return 1e9
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _C_and_grad_h(h, w):
    """C(h) and gradient wrt h, using weights w over active max knots (sum 1)."""
    N = len(h)
    S = h.sum()
    conv = np.convolve(h, h)
    m = np.dot(w, conv[w > 0]) if np.any(w > 0) else conv.max()
    C = 2.0 * N * m / (S * S)
    # dC/dh via conv gradient
    # sum_j w_j * conv[j]; conv[j] = sum_i h[i] h[j-i]; d/dh[i] = 2 h[j-i]
    g_h = np.full(N, -2.0 * C / S)
    # weighted contribution: 2N/S^2 * sum_j w_j * 2 h[j-i]
    for j in np.nonzero(w)[0]:
        i_lo = max(0, j - N + 1)
        i_hi = min(N - 1, j)
        if i_lo <= i_hi:
            idx = np.arange(i_lo, i_hi + 1)
            g_h[idx] += 4.0 * N / (S * S) * w[j] * h[j - idx]
    return C, g_h


def _active_weights(conv, m, tol=1e-7):
    active = np.where(conv >= m - tol * max(1.0, abs(m)))[0]
    w = np.zeros(len(conv))
    if len(active) > 0:
        w[active] = 1.0 / len(active)
    return w


def _polish(z0, budget_deadline):
    """L-BFGS-B on log heights with exact subgradient."""
    N = len(z0)

    def fun(z):
        h = np.exp(np.clip(z, -20, 20))
        S = h.sum()
        if S <= 0:
            return 1e9, np.zeros(N)
        conv = np.convolve(h, h)
        m = conv.max()
        w = _active_weights(conv, m)
        C, g_h = _C_and_grad_h(h, w)
        g_z = h * g_h
        return C, g_z

    try:
        res = minimize(fun, z0, jac=True, method='L-BFGS-B',
                       bounds=[(-20.0, 20.0)] * N,
                       options={'maxiter': 20000, 'ftol': 1e-16, 'gtol': 1e-14,
                                'maxcor': 30})
        h = np.exp(np.clip(res.x, -20, 20))
        return h, _C(h)
    except Exception:
        h = np.exp(np.clip(z0, -20, 20))
        return h, _C(h)


def _resample(h, newN):
    """Resample heights onto newN steps preserving shape (nearest / interp)."""
    oldN = len(h)
    if oldN == newN:
        return h.copy()
    x_old = (np.arange(oldN) + 0.5) / oldN
    x_new = (np.arange(newN) + 0.5) / newN
    return np.interp(x_new, x_old, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    margin = 1.5
    deadline = budget_seconds - margin

    if start is not None:
        h0 = np.asarray(start, dtype=float)
        if h0.sum() <= 0 or not np.all(np.isfinite(h0)):
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 200
        x = np.linspace(-0.25, 0.25, N, endpoint=False) + 0.25 / N
        h0 = np.exp(-2.6 * (x - x.min()))

    h0 = np.maximum(h0, 1e-12)
    best_h = h0.copy()
    best_C = _C(h0)
    start_C = best_C

    def time_left():
        return deadline - (time.process_time() - t0)

    # Phase 1: polish from start
    if time_left() > 2.0:
        h, C = _polish(np.log(best_h), deadline)
        if C < best_C:
            best_C = C
            best_h = h

    # Phase 2: try different N values (resample up/down then polish).
    # More steps can sharpen the near-flat maximum region.
    rng = np.random.RandomState(20240517)
    Ns_try = []
    curN = len(best_h)
    # Prefer increasing resolution moderately, plus a few nearby options
    for mult in (1.5, 2.0, 2.5, 3.0):
        n = int(round(curN * mult))
        if 2 <= n <= 30000:
            Ns_try.append(n)
    for n in (curN, curN + 20, curN + 50):
        if 2 <= n <= 30000:
            Ns_try.append(n)

    tried = set()
    for n in Ns_try:
        if time_left() < 2.0:
            break
        if n in tried:
            continue
        tried.add(n)
        h_rs = _resample(best_h, n)
        h_rs = np.maximum(h_rs, 1e-12)
        h_pol, C_pol = _polish(np.log(h_rs), deadline)
        if C_pol < best_C:
            best_C = C_pol
            best_h = h_pol

    # Phase 3: perturbation restarts on current best
    for k in range(8):
        if time_left() < 2.0:
            break
        scale = 0.005 * (1.0 + 0.5 * k)
        z = np.log(np.maximum(best_h, 1e-12)) + rng.normal(0.0, scale, size=len(best_h))
        h_pol, C_pol = _polish(z, deadline)
        if C_pol < best_C:
            best_C = C_pol
            best_h = h_pol

    print("final C = %.6f (start %.6f, N=%d)" % (best_C, start_C, len(best_h)))
    return best_h

import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return 1e9
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _C_and_grad_log(h):
    N = len(h)
    S = h.sum()
    conv = np.convolve(h, h)
    k = int(np.argmax(conv))
    C = 2.0 * N * conv[k] / (S * S)
    g = np.full(N, -2.0 * C / S)
    i_lo = max(0, k - N + 1)
    i_hi = min(N - 1, k)
    if i_lo <= i_hi:
        idx = np.arange(i_lo, i_hi + 1)
        g[idx] += 4.0 * N * h[k - idx] / (S * S)
    return C, h * g


def _sym_from_u(u):
    return np.concatenate([u, u[::-1]])


def _resample(h, N_target):
    N = len(h)
    x_src = (np.arange(N) + 0.5) / N
    x_dst = (np.arange(N_target) + 0.5) / N_target
    return np.interp(x_dst, x_src, h)


def _optimize_sym(u0, t0, budget, maxiter=3000):
    logu0 = np.log(np.maximum(u0, 1e-12))
    n = len(u0)

    def fun(logu):
        if time.process_time() - t0 > budget:
            raise TimeoutError
        u = np.exp(np.clip(logu, -20, 20))
        h = _sym_from_u(u)
        C, g_log = _C_and_grad_log(h)
        g = g_log[:n] + g_log[n:][::-1]
        return C, g

    try:
        res = minimize(fun, logu0, jac=True, method='L-BFGS-B',
                       bounds=[(-20, 20)] * n,
                       options={'maxiter': maxiter, 'ftol': 1e-15, 'gtol': 1e-13})
        u = np.exp(np.clip(res.x, -20, 20))
        h = _sym_from_u(u)
        return h, _C(h)
    except TimeoutError:
        return None, np.inf
    except Exception:
        return None, np.inf


def _polish_full(h0, t0, budget, maxiter=800):
    logh0 = np.log(np.maximum(h0, 1e-12))
    N = len(h0)

    def fun(logh):
        if time.process_time() - t0 > budget:
            raise TimeoutError
        h = np.exp(np.clip(logh, -20, 20))
        return _C_and_grad_log(h)

    try:
        res = minimize(fun, logh0, jac=True, method='L-BFGS-B',
                       bounds=[(-20, 20)] * N,
                       options={'maxiter': maxiter, 'ftol': 1e-15, 'gtol': 1e-13})
        h = np.exp(np.clip(res.x, -20, 20))
        return h, _C(h)
    except TimeoutError:
        return None, np.inf
    except Exception:
        return None, np.inf


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 1.0

    if start is not None:
        h0 = np.asarray(start, dtype=float)
        if h0.sum() <= 0 or not np.all(np.isfinite(h0)):
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 200
        x = np.linspace(-1, 1, N)
        h0 = np.exp(-2.0 * x * x)

    best_h = h0.copy()
    best_C = _C(h0)
    start_C = best_C
    print("start C = %.6f, N=%d" % (start_C, len(h0)))

    # Progressive increasing resolution, symmetrize at each level
    schedule = [400, 800, 1600, 3200, 6400, 12800, 25600]
    for N_target in schedule:
        if time.process_time() - t0 > deadline - 0.3:
            break
        h_r = _resample(best_h, N_target)
        # symmetrize
        h_r = 0.5 * (h_r + h_r[::-1])
        half = N_target // 2
        u0 = h_r[:half].copy()
        c_init = _C(_sym_from_u(u0))
        if c_init < best_C:
            best_C = c_init
            best_h = _sym_from_u(u0)
        h_s, C_s = _optimize_sym(u0, t0, deadline, maxiter=2000)
        if h_s is not None and C_s < best_C:
            best_C = C_s
            best_h = h_s
        print("N=%d C = %.6f" % (N_target, best_C))
        if time.process_time() - t0 > deadline - 0.3:
            break

    # Final full polish at current size
    if time.process_time() - t0 < deadline - 0.3:
        h_p, C_p = _polish_full(best_h, t0, deadline, maxiter=600)
        if h_p is not None and C_p < best_C:
            best_C = C_p
            best_h = h_p
        print("after polish C = %.6f" % best_C)

    if best_h.max() > 0:
        best_h = best_h / best_h.max()
    print("final C = %.6f (start %.6f), N=%d" % (best_C, start_C, len(best_h)))
    return best_h

