def _polish(h0, max_iter=800):
    """L-BFGS-B in log-space, gradient averaged over active max knots."""
    N = len(h0)
    h0 = np.maximum(np.asarray(h0, dtype=float), 1e-12)
    logh0 = np.log(h0 / h0.max())

    def obj_grad(logh):
        h = np.exp(np.clip(logh, -20, 20))
        S = h.sum()
        if S <= 0:
            return 1e9, np.zeros(N)
        conv = np.convolve(h, h)
