        active = np.where(conv >= m - 1e-10 * max(1.0, abs(m)))[0]
        na = len(active)
        g_h = np.full(N, -2.0 * C / S)
        for j in active:
            i_lo = max(0, j - N + 1)
            i_hi = min(N - 1, j)
            if i_lo <= i_hi:
                idx = np.arange(i_lo, i_hi + 1)
                g_h[idx] += 4.0 * N * h[j - idx] / (S * S * na)
        g_log = h * g_h
        return C, g_log

    try:
        res = minimize(obj_grad, logh0, jac=True, method='L-BFGS-B',
                       options={'maxiter': max_iter, 'maxfun': max_iter * 2,
                                'ftol': 1e-15, 'gtol': 1e-12, 'maxcor': 30})
        h = np.exp(np.clip(res.x, -20, 20))
        h = h / h.max()
        return h, _C(h)
