import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return 1e9
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _softmax_C_and_grad(z, beta):
    N = len(z)
    h = np.exp(np.clip(z, -20, 20))
    S = h.sum()
    if S <= 0:
        return 1e9, np.zeros(N)
    conv = np.convolve(h, h)
    b = beta * conv
    bmax = b.max()
    e = np.exp(b - bmax)
    Z = e.sum()
    lse = bmax + np.log(Z)
    M = lse / beta
    C = 2.0 * N * M / (S * S)
    w = e / Z

    g_M = np.zeros(N)
    for i in range(N):
        js = np.arange(i, i + N)
        g_M[i] = 2.0 * np.dot(w[js], h[js - i])

    g_h = (2.0 * N / (S * S)) * g_M - 2.0 * C / S
    g_z = h * g_h
    return C, g_z


def _polish_soft(z0, beta):
    def fun(z):
        return _softmax_C_and_grad(z, beta)
    try:
        res = minimize(fun, z0, jac=True, method='L-BFGS-B',
                       bounds=[(-20.0, 20.0)] * len(z0),
                       options={'maxiter': 2000, 'ftol': 1e-14, 'gtol': 1e-12,
                                'maxcor': 20})
        return res.x
    except Exception:
        return z0


def _hard_polish(z0):
    def hard_fun(z):
        N = len(z)
        h = np.exp(np.clip(z, -20, 20))
        S = h.sum()
        if S <= 0:
            return 1e9, np.zeros(N)
        conv = np.convolve(h, h)
        m = conv.max()
        C = 2.0 * N * m / (S * S)
        active = np.where(conv >= m - 1e-8 * max(1.0, abs(m)))[0]
        g_h = np.full(N, -2.0 * C / S)
        for j in active:
            i_lo = max(0, j - N + 1)
            i_hi = min(N - 1, j)
            if i_lo <= i_hi:
                idx = np.arange(i_lo, i_hi + 1)
                g_h[idx] += 2.0 * (2.0 * N / (S * S)) * (1.0 / len(active)) * h[j - idx]
        return C, h * g_h
    try:
        res = minimize(hard_fun, z0, jac=True, method='L-BFGS-B',
                       bounds=[(-20.0, 20.0)] * len(z0),
                       options={'maxiter': 3000, 'ftol': 1e-14, 'gtol': 1e-12, 'maxcor': 20})
        return res.x
    except Exception:
        return z0


def _anneal_and_polish(h0, betas, deadline, t0):
    z = np.log(np.maximum(h0, 1e-12))
    best_h = h0.copy()
    best_C = _C(h0)
    for beta in betas:
        if time.process_time() - t0 > deadline:
            break
        z = _polish_soft(z, beta)
        h = np.exp(np.clip(z, -20, 20))
        C = _C(h)
        if C < best_C:
            best_C = C
            best_h = h
    if time.process_time() - t0 < deadline:
        z = _hard_polish(z)
        h = np.exp(np.clip(z, -20, 20))
        C = _C(h)
        if C < best_C:
            best_C = C
            best_h = h
    return best_h, best_C


class _Timeout(Exception):
    pass


def _downsample(h, K):
    Ns = len(h)
    idx = np.linspace(0, Ns, K + 1).astype(int)
    blocks = np.array([h[idx[i]:idx[i + 1]].mean() if idx[i + 1] > idx[i]
                       else h[idx[i]] for i in range(K)])
    return np.maximum(blocks, 1e-9)


def _block_obj(zb):
    K = len(zb)
    hb = np.exp(np.clip(zb, -20, 20))
    s = hb.sum()
    if s <= 0:
        return 1e9
    return 2.0 * K * np.max(np.convolve(hb, hb)) / (s * s)


def _opt_block(zb0, deadline):
    block_best = zb0.copy()
    block_best_C = _block_obj(zb0)

    def wrapped(zb):
        if time.process_time() > deadline:
            raise _Timeout()
        return _block_obj(zb)

    for method in ['Powell', 'Nelder-Mead']:
        if time.process_time() > deadline:
            break
        try:
            res = minimize(wrapped, block_best, method=method,
                           options={'maxiter': 4000, 'xtol': 1e-10, 'ftol': 1e-12}
                           if method == 'Powell' else
                           {'maxiter': 4000, 'xatol': 1e-8, 'fatol': 1e-12})
            zb = res.x
            c = _block_obj(zb)
            if c < block_best_C:
                block_best_C = c
                block_best = zb
        except _Timeout:
            break
        except Exception:
            pass
    return block_best, block_best_C


def _upsample(hb, N2):
    K = len(hb)
    xb = np.linspace(0, 1, K)
    xn = np.linspace(0, 1, N2)
    h_up = np.interp(xn, xb, hb)
    return np.maximum(h_up, 1e-12)


def construct(budget_seconds, start):
    t0 = time.process_time()
    margin = 1.5
    deadline = budget_seconds - margin

    if start is not None:
        h_start = np.asarray(start, dtype=float)
        if h_start.sum() <= 0 or not np.all(np.isfinite(h_start)):
            h_start = None
    else:
        h_start = None

    if h_start is None:
        N = 200
        x = np.linspace(-0.25, 0.25, N, endpoint=False) + 0.25 / N
        h_start = np.exp(-2.6 * (x - x.min()))

    h_start = np.maximum(h_start, 1e-12)
    best_h = h_start.copy()
    best_C = _C(h_start)
    start_C = best_C

    rng = np.random.default_rng(12345)

    # --- Multi-start coarse block search ---
    coarse_deadline = t0 + min(7.0, 0.5 * (deadline - t0))
    Ks = [40, 60, 80]
    n_perturb = 5
    sigma = 0.7

    block_candidates = []  # (C, zb)

    for K in Ks:
        blocks = _downsample(h_start, K)
        zb_base = np.log(blocks)
        starts = [zb_base]
        for _ in range(n_perturb):
            starts.append(zb_base + rng.normal(0.0, sigma, size=K))

        for zb0 in starts:
            if time.process_time() > coarse_deadline:
                break
            zb, c = _opt_block(zb0, coarse_deadline)
            block_candidates.append((c, zb))
        if time.process_time() > coarse_deadline:
            break

    block_candidates.sort(key=lambda t: t[0])
    top = block_candidates[:3]
    best_block_C = top[0][0] if top else 1e9

    # Upsample top 3 and polish
    N2 = 400
    for c_blk, zb in top:
        if time.process_time() > deadline:
            break
        hb = np.exp(np.clip(zb, -20, 20))
        h_up = _upsample(hb, N2)
        h_cand, C_cand = _anneal_and_polish(h_up, [100.0, 1000.0, 5000.0], deadline, t0)
        if C_cand < best_C:
            best_C = C_cand
            best_h = h_cand

    # Also polish the start itself if time remains
    if time.process_time() < deadline:
        h_s2, C_s2 = _anneal_and_polish(h_start, [100.0, 1000.0, 5000.0], deadline, t0)
        if C_s2 < best_C:
            best_C = C_s2
            best_h = h_s2

    print("final C = %.6f (start %.6f) blockC=%.6f nblocks=%d"
          % (best_C, start_C, best_block_C, len(block_candidates)))
    return best_h

