    if h_start is None:
        N = 400
        x = np.linspace(-0.25, 0.25, N, endpoint=False) + 0.25 / N
        h_start = np.exp(-2.6 * (x - x.min()))

    h_start = np.maximum(h_start, 1e-12)
    best_h = h_start.copy()
    best_C = _C(h_start)

    # KEY CHANGE: accept higher resolution than the start. The prior program
    # capped at N=1600 which made C worse (discretization). Go to 6000-8000
    # with a coarse-to-fine ladder and spend the whole budget there.
    ladder = [2000, 4000, 6000, 8000]
    betas_hi = [1e4, 1e5, 1e6, 1e7, 1e8]

    h_cur = best_h
    for lvl, N_target in enumerate(ladder):
        if time.process_time() > deadline - 0.5:
            break
        h_up = np.maximum(_upsample(h_cur, N_target), 1e-12)
        remaining = deadline - time.process_time()
        levels_left = len(ladder) - lvl
        slice_deadline = time.process_time() + max(0.5, remaining / max(1, levels_left))
        if N_target <= 2000:
            ms, mh = 2000, 3000
        elif N_target <= 4000:
            ms, mh = 1200, 1500
        else:
            ms, mh = 600, 800
        h_new, C_new = _refine_at_N(h_up, betas_hi, slice_deadline, t0,
                                    maxiter_soft=ms, maxiter_hard=mh)
        if C_new < _C_fft(h_cur):
            h_cur = h_new
        print("level N=%d  C=%.6f  t=%.2f" % (len(h_cur), _C_fft(h_cur),
                                              time.process_time() - t0))

    # final exact check; also compare against downsampled versions
    best_exact = h_cur.copy()
    best_exact_C = _C(h_cur)
    for f in (2, 4):
        if len(h_cur) % f == 0:
            hd = h_cur.reshape(len(h_cur) // f, f).mean(axis=1)
            Cd = _C(hd)
            if Cd < best_exact_C:
                best_exact = hd
                best_exact_C = Cd

    print("final C = %.6f  N=%d" % (best_exact_C, len(best_exact)))
    return best_exact

