        z = _polish_soft(z, beta, maxiter=maxiter_soft)
        h = _softplus(z)
        C = _C_fft(h)
        if C < best_C:
            best_C = C
            best_h = h
    if deadline - (time.process_time() - t0) > 1.0:
        z = _hard_polish(z, maxiter=maxiter_hard)
        h = _softplus(z)
        C = _C_fft(h)
        if C < best_C:
            best_C = C
            best_h = h
    return best_h, best_C


