    if s <= 0:
        return 1e9
    return 2.0 * len(h) * float(np.max(fftconvolve(h, h, 'full'))) / (s * s)


def _softmax_C_and_grad(z, beta):
    N = len(z)
    h = np.exp(np.clip(z, -20, 20))
    S = h.sum()
    if S <= 0:
        return 1e9, np.zeros(N)
    conv = fftconvolve(h, h, 'full')
    b = beta * conv
    bmax = b.max()
    e = np.exp(b - bmax)
    Z = e.sum()
    lse = bmax + np.log(Z)
    M = lse / beta
    C = 2.0 * N * M / (S * S)
    w = e / Z
    g_M = fftconvolve(w, h[::-1], 'full')[N - 1:2 * N - 1]
    g_h = (2.0 * N / (S * S)) * g_M - 2.0 * C / S
    g_z = h * g_h
    return C, g_z


