    best_cos_C = 1e9

    def obj(p):
        a, phi = p
        h = _cosine_h(N_cos, a, phi)
        if h.sum() <= 0:
            return 1e9
        return _C_fft(h)

    # coarse scan over phi at a few amplitudes, then Nelder-Mead
    try:
        for a0 in (-0.9, -0.5, 0.0, 0.5, 0.9):
            for phi0 in np.linspace(0, 2 * np.pi, 8, endpoint=False):
                if time.process_time() - t0 > deadline - 6.0:
                    break
                val = obj((a0, phi0))
                if val < best_cos_C:
