                best_cos_h = _cosine_h(N_cos, res.x[0], res.x[1])
        except Exception:
            pass

    if best_cos_h is not None:
        print("cosine best C=%.6f" % best_cos_C)

    # pick the better of cosine result and start (upsampled to N_cos)
    h_cur = best_h
    if best_cos_h is not None and best_cos_C < _C_fft(_upsample(best_h, N_cos)):
