import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _C(h):
    s = h.sum()
    if s <= 0:
        return 1e9
    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _C_fft(h):
    s = h.sum()
    if s <= 0:
        return 1e9
    return 2.0 * len(h) * float(np.max(fftconvolve(h, h, 'full'))) / (s * s)


def _C_and_grad_log(h):
    N = len(h)
    S = h.sum()
    conv = fftconvolve(h, h, 'full')
    k = int(np.argmax(conv))
    m = conv[k]
    C = 2.0 * N * m / (S * S)
    g = np.full(N, -2.0 * C / S)
    i_lo = max(0, k - N + 1)
    i_hi = min(N - 1, k)
    if i_lo <= i_hi:
        idx = np.arange(i_lo, i_hi + 1)
        g[idx] += 4.0 * N * h[k - idx] / (S * S)
    return C, h * g


def _optimize_sym(u0, t0, deadline, maxiter=2000):
    logu0 = np.log(np.maximum(u0, 1e-12))

    def fun(logu):
        if time.process_time() > deadline:
            raise TimeoutError
        u = np.exp(np.clip(logu, -20, 20))
        h = np.concatenate([u, u[::-1]])
        C, g_log = _C_and_grad_log(h)
        n = len(u)
        g = g_log[:n] + g_log[n:][::-1]
        return C, g

    try:
        res = minimize(fun, logu0, jac=True, method='L-BFGS-B',
                       bounds=[(-20, 20)] * len(u0),
                       options={'maxiter': maxiter, 'ftol': 1e-15,
                                'gtol': 1e-13, 'maxcor': 30})
        u = np.exp(np.clip(res.x, -20, 20))
        h = np.concatenate([u, u[::-1]])
        return h, _C(h)
    except Exception:
        return None, np.inf


def _polish_full(h0, t0, deadline, maxiter=800):
    logh0 = np.log(np.maximum(h0, 1e-12))

    def fun(logh):
        if time.process_time() > deadline:
            raise TimeoutError
        h = np.exp(np.clip(logh, -20, 20))
        return _C_and_grad_log(h)

    try:
        res = minimize(fun, logh0, jac=True, method='L-BFGS-B',
                       bounds=[(-20, 20)] * len(h0),
                       options={'maxiter': maxiter, 'ftol': 1e-15,
                                'gtol': 1e-13, 'maxcor': 30})
        h = np.exp(np.clip(res.x, -20, 20))
        return h, _C(h)
    except Exception:
        return None, np.inf


def _upsample(h, N_target):
    N_cur = len(h)
    if N_cur == N_target:
        return h.copy()
    x_old = np.linspace(0, 1, N_cur, endpoint=False)
    x_new = np.linspace(0, 1, N_target, endpoint=False)
    return np.interp(x_new, x_old, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    margin = 1.5
    deadline = budget_seconds - margin

    if start is not None:
        h0 = np.asarray(start, dtype=float)
        if h0.sum() <= 0 or not np.all(np.isfinite(h0)):
            h0 = None
    else:
        h0 = None

    if h0 is None:
        N = 200
        x = np.linspace(-1, 1, N)
        h0 = np.exp(-2.0 * x * x)

    best_h = h0.copy()
    best_C = _C(h0)
    start_C = best_C

    # Try increasing N levels. Higher N gives a finer discretization of the
    # true optimal f; optimize from an upsampled version of the current best.
    for N_target in (400, 800, 1600):
        if time.process_time() > deadline - 1.0:
            break
        h_up = np.maximum(_upsample(best_h, N_target), 1e-12)
        # Symmetrize
        h_sym = 0.5 * (h_up + h_up[::-1])
        half = N_target // 2
        u0 = h_sym[:half].copy()

        h_opt, C_opt = _optimize_sym(u0, t0, deadline - 0.5, maxiter=1500)
        if h_opt is not None and C_opt < best_C:
            best_C = C_opt
            best_h = h_opt
        print("N=%d sym: C=%.6f t=%.2f" % (N_target, best_C,
                                           time.process_time() - t0))

    # Final full polish at current N
    if time.process_time() < deadline - 0.5:
        h_p, C_p = _polish_full(best_h, t0, deadline, maxiter=500)
        if h_p is not None and C_p < best_C:
            best_C = C_p
            best_h = h_p
        print("full polish: C=%.6f" % best_C)

    if best_h.max() > 0:
        best_h = best_h / best_h.max()

    print("final C = %.6f (start %.6f) N=%d" % (best_C, start_C, len(best_h)))
    return best_h

