import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _C(h):
    s = np.sum(h)
    if s <= 0:
        return 1e9
    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _C_fft(h):
    s = np.sum(h)
    if s <= 0:
        return 1e9
    return 2.0 * len(h) * float(np.max(fftconvolve(h, h, 'full'))) / (s * s)


def _soft_C_grad(z, beta, N):
    h = np.exp(np.clip(z, -20, 20))
    S = h.sum()
    if S <= 0:
        return 1e9, np.zeros(N)
    conv = fftconvolve(h, h, 'full')
    b = beta * conv
    bmax = b.max()
    e = np.exp(b - bmax)
    Z = e.sum()
    lse = bmax + np.log(Z)
    M = lse / beta
    C = 2.0 * N * M / (S * S)
    w = e / Z
    g_M = fftconvolve(w, h[::-1], 'full')[N - 1:2 * N - 1]
    g_h = (2.0 * N / (S * S)) * g_M - 2.0 * C / S
    return C, h * g_h


def _hard_C_grad(z, N):
    h = np.exp(np.clip(z, -20, 20))
    S = h.sum()
    if S <= 0:
        return 1e9, np.zeros(N)
    conv = fftconvolve(h, h, 'full')
    m = conv.max()
    C = 2.0 * N * m / (S * S)
    active = np.where(conv >= m - 1e-9 * max(1.0, abs(m)))[0]
    mask = np.zeros(2 * N - 1)
    mask[active] = 1.0
    na = max(1, len(active))
    corr = fftconvolve(mask, h[::-1], 'full')[N - 1:2 * N - 1]
    g_h = -2.0 * C / S + (4.0 * N / (S * S)) * (1.0 / na) * corr
    return C, h * g_h


def _polish(z0, beta, N, maxiter, mode):
    if mode == 'soft':
        fun = lambda z: _soft_C_grad(z, beta, N)
    else:
        fun = lambda z: _hard_C_grad(z, N)
    try:
        res = minimize(fun, z0, jac=True, method='L-BFGS-B',
                       bounds=[(-20.0, 20.0)] * len(z0),
                       options={'maxiter': maxiter, 'ftol': 1e-15,
                                'gtol': 1e-13, 'maxcor': 30})
        return res.x
    except Exception:
        return z0


def _refine(h0, betas, deadline, extra_hard=True):
    N = len(h0)
    z = np.log(np.maximum(h0, 1e-12))
    best_h = h0.copy()
    best_C = _C_fft(h0)
    for beta in betas:
        if time.process_time() > deadline:
            break
        z = _polish(z, beta, N, 600, 'soft')
        h = np.exp(np.clip(z, -20, 20))
        C = _C_fft(h)
        if C < best_C:
            best_C = C
            best_h = h
    if extra_hard and time.process_time() < deadline:
        z = _polish(z, None, N, 800, 'hard')
        h = np.exp(np.clip(z, -20, 20))
        C = _C_fft(h)
        if C < best_C:
            best_C = C
            best_h = h
    return best_h, best_C


def _upsample(h, N_target):
    N_cur = len(h)
    if N_cur == N_target:
        return h.copy()
    if N_target % N_cur == 0:
        return np.repeat(h, N_target // N_cur)
    if N_cur % N_target == 0:
        f = N_cur // N_target
        return h[:f * N_target].reshape(N_target, f).mean(axis=1)
    x_old = np.linspace(0, 1, N_cur, endpoint=False)
    x_new = np.linspace(0, 1, N_target, endpoint=False)
    return np.interp(x_new, x_old, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 3.0

    if start is not None:
        h_start = np.asarray(start, dtype=float)
        if h_start.sum() <= 0 or not np.all(np.isfinite(h_start)):
            h_start = None
    else:
        h_start = None

    if h_start is None:
        N = 400
        x = np.linspace(0, 1, N, endpoint=False)
        h_start = np.exp(-2.6 * x)
    h_start = np.maximum(h_start, 1e-12)

    best_h = h_start.copy()
    best_C = _C(best_h)

    # Stage A: refine at current resolution
    if time.process_time() < deadline - 8.0:
        hh, CC = _refine(best_h, [1e3, 1e5, 1e7], deadline - 8.0)
        if CC < best_C:
            best_C, best_h = CC, hh
        print("A N=%d C=%.6f" % (len(best_h), best_C))

    # Stage B: upsample to 1600 and refine
    if time.process_time() < deadline - 4.0:
