        if CC < _C(best_h):
            best_C, best_h = CC, hh
        print("C N=%d C=%.6f" % (len(best_h), best_C))

    # Try downsampling to reduce exact C
    best_exact = best_h.copy()
    best_exact_C = _C(best_h)
    for f in (2, 4, 8):
        if len(best_h) % f == 0:
            hd = best_h.reshape(len(best_h) // f, f).mean(axis=1)
            Cd = _C(hd)
            if Cd < best_exact_C:
