import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _C(h):
    s = h.sum()
    if s <= 0:
        return 1e9
    return 2.0 * len(h) * float(np.max(fftconvolve(h, h, 'full'))) / (s * s)


def _soft_C_grad(z, beta):
    N = len(z)
    h = np.exp(np.clip(z, -20, 20))
    S = h.sum()
    if S <= 0:
        return 1e9, np.zeros(N)
    conv = fftconvolve(h, h, 'full')
    b = beta * conv
    bmax = b.max()
    e = np.exp(b - bmax)
    Z = e.sum()
    lse = bmax + np.log(Z)
    M = lse / beta
    C = 2.0 * N * M / (S * S)
    w = e / Z
    g_M = 2.0 * fftconvolve(w, h[::-1], 'full')[N - 1:2 * N - 1]
    g_h = (2.0 * N / (S * S)) * g_M - 2.0 * C / S
    return C, h * g_h


def _soft_polish(z0, beta, deadline, t0, maxiter=2000):
    def cb(xk):
        return time.process_time() - t0 > deadline
    try:
        res = minimize(lambda z: _soft_C_grad(z, beta), z0, jac=True,
                       method='L-BFGS-B', bounds=[(-20.0, 20.0)] * len(z0),
                       callback=cb,
                       options={'maxiter': maxiter, 'ftol': 1e-16,
                                'gtol': 1e-14, 'maxcor': 30})
        return res.x
    except Exception:
        return z0


def _hard_C_grad(z, delta):
    N = len(z)
    h = np.exp(np.clip(z, -20, 20))
    S = h.sum()
    if S <= 0:
        return 1e9, np.zeros(N)
    conv = fftconvolve(h, h, 'full')
    m = conv.max()
    C = 2.0 * N * m / (S * S)
    # smooth-max via softplus around max for gradient
    thr = m - delta * max(1.0, abs(m))
    active = conv >= thr
    na = active.sum()
    if na == 0:
        return C, h * (-2.0 * C / S)
    w = active.astype(float) / na
    corr = fftconvolve(w, h[::-1], 'full')[N - 1:2 * N - 1]
    g_h = -2.0 * C / S + (4.0 * N / (S * S)) * corr
    return C, h * g_h


def _hard_polish(z0, delta, deadline, t0, maxiter=3000):
    def cb(xk):
        return time.process_time() - t0 > deadline
    try:
        res = minimize(lambda z: _hard_C_grad(z, delta), z0, jac=True,
                       method='L-BFGS-B', bounds=[(-20.0, 20.0)] * len(z0),
                       callback=cb,
                       options={'maxiter': maxiter, 'ftol': 1e-16,
                                'gtol': 1e-14, 'maxcor': 30})
        return res.x
    except Exception:
        return z0


def _upsample(h, N_new):
    N_old = len(h)
    if N_new == N_old:
        return h.copy()
    if N_new % N_old == 0:
        return np.repeat(h, N_new // N_old)
    x_old = (np.arange(N_old) + 0.5) / N_old
    x_new = (np.arange(N_new) + 0.5) / N_new
    return np.interp(x_new, x_old, h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    margin = 1.5
    deadline = budget_seconds - margin

    def rem():
        return deadline - (time.process_time() - t0)

    if start is not None:
        h0 = np.asarray(start, dtype=float)
        if h0.sum() <= 0 or not np.all(np.isfinite(h0)):
            h0 = None
    else:
        h0 = None
    if h0 is None:
        N = 400
        x = np.linspace(0, 1, N)
        h0 = np.exp(-2.6 * x)

    h0 = np.maximum(h0, 1e-12)
    start_C = _C(h0)
    best_h = h0.copy()
    best_C = start_C
    print("start C=%.6f N=%d" % (start_C, len(h0)))

    # Phase 1: refine at current N with soft-max betas, then hard polish
    z = np.log(h0)
    for beta in [3000.0, 10000.0, 30000.0, 100000.0, 300000.0]:
        if rem() < 1.0:
            break
        z = _soft_polish(z, beta, deadline - 0.5, t0)
        h = np.exp(np.clip(z, -20, 20))
        C = _C(h)
        if C < best_C:
            best_C, best_h = C, h.copy()
    if rem() > 0.5:
        z = _hard_polish(z, 1e-9, deadline - 0.3, t0)
        h = np.exp(np.clip(z, -20, 20))
        C = _C(h)
        if C < best_C:
            best_C, best_h = C, h.copy()
    print("phase1 C=%.6f t=%.2f" % (best_C, time.process_time() - t0))

    # Phase 2: upsample to larger N and refine
    for Nt in [4800, 9600, 19200]:
        if rem() < 2.0:
            break
        if Nt <= len(best_h):
            continue
        h_up = np.maximum(_upsample(best_h, Nt), 1e-12)
        z = np.log(h_up)
        for beta in [30000.0, 100000.0, 300000.0]:
            if rem() < 1.0:
                break
            z = _soft_polish(z, beta, deadline - 0.5, t0, maxiter=800)
        if rem() > 0.5:
            z = _hard_polish(z, 1e-9, deadline - 0.3, t0, maxiter=1200)
        h = np.exp(np.clip(z, -20, 20))
        C = _C(h)
        if C < best_C:
            best_C, best_h = C, h.copy()
        print("N=%d C=%.6f t=%.2f" % (Nt, best_C, time.process_time() - t0))

    # Phase 3: if still time, try exact 2x on best then hard polish
    if rem() > 2.0 and len(best_h) * 2 <= 30000:
        N_up = len(best_h) * 2
        h_up = np.maximum(np.repeat(best_h, 2), 1e-12)
        z = np.log(h_up)
        z = _hard_polish(z, 1e-9, deadline - 0.5, t0, maxiter=1500)
        h = np.exp(np.clip(z, -20, 20))
        C = _C(h)
        if C < best_C:
            best_C, best_h = C, h.copy()
        print("2x C=%.6f t=%.2f" % (best_C, time.process_time() - t0))

    print("final C = %.9f (start %.9f) N=%d t=%.2f" %
          (best_C, start_C, len(best_h), time.process_time() - t0))
    return best_h

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _C(h):
    s = h.sum()
    if s <= 0:
        return 1e9
    return 2.0 * len(h) * float(np.max(np.convolve(h, h))) / (s * s)


def _C_fft(h):
    s = h.sum()
    if s <= 0:
        return 1e9
    return 2.0 * len(h) * float(np.max(fftconvolve(h, h, 'full'))) / (s * s)


def _softmax_C_and_grad(z, beta):
    N = len(z)
    h = np.exp(np.clip(z, -20, 20))
    S = h.sum()
    if S <= 0:
        return 1e9, np.zeros(N)
    conv = fftconvolve(h, h, 'full')
    b = beta * conv
    bmax = b.max()
    e = np.exp(b - bmax)
    Z = e.sum()
    lse = bmax + np.log(Z)
    M = lse / beta
    C = 2.0 * N * M / (S * S)
    w = e / Z
    g_M = 2.0 * fftconvolve(w, h[::-1], 'full')[N - 1:2 * N - 1]
    g_h = (2.0 * N / (S * S)) * g_M - 2.0 * C / S
    g_z = h * g_h
    return C, g_z


def _polish_soft(z0, beta, maxiter, deadline, t0):
    def fun(z):
        return _softmax_C_and_grad(z, beta)

    def cb(xk):
        return time.process_time() - t0 > deadline
    try:
        res = minimize(fun, z0, jac=True, method='L-BFGS-B',
                       bounds=[(-20.0, 20.0)] * len(z0),
                       callback=cb,
                       options={'maxiter': maxiter, 'ftol': 1e-15, 'gtol': 1e-13,
                                'maxcor': 30})
        return res.x
    except Exception:
        return z0


def _hard_polish_fixed(z0, maxiter, deadline, t0, tol_rel=1e-6):
    def hard_fun(z):
        N = len(z)
        h = np.exp(np.clip(z, -20, 20))
        S = h.sum()
        if S <= 0:
            return 1e9, np.zeros(N)
        conv = fftconvolve(h, h, 'full')
        m = conv.max()
        C = 2.0 * N * m / (S * S)
        tol = tol_rel * max(1.0, abs(m))
        active = np.where(conv >= m - tol)[0]
        mask = np.zeros(N + N - 1)
        mask[active] = 1.0
        na = float(len(active))
        corr = fftconvolve(mask, h[::-1], 'full')[N - 1:2 * N - 1]
        g_h = -2.0 * C / S + (4.0 * N / (S * S)) * (1.0 / na) * corr
        return C, h * g_h

    def cb(xk):
        return time.process_time() - t0 > deadline
    try:
        res = minimize(hard_fun, z0, jac=True, method='L-BFGS-B',
                       bounds=[(-20.0, 20.0)] * len(z0),
                       callback=cb,
                       options={'maxiter': maxiter, 'ftol': 1e-15, 'gtol': 1e-13,
                                'maxcor': 40})
