    N_cur = len(h)
    if N_cur == N_target:
        return h.copy()
    if N_target % N_cur == 0:
        return np.repeat(h, N_target // N_cur)
    if N_cur % N_target == 0:
        f = N_cur // N_target
        return h[:f * N_target].reshape(N_target, f).mean(axis=1)
    x_old = np.linspace(0, 1, N_cur, endpoint=False)
    x_new = np.linspace(0, 1, N_target, endpoint=False)
    return np.interp(x_new, x_old, h)


def _downsample(h, N_target):
    N_cur = len(h)
    if N_cur == N_target:
        return h.copy()
    if N_cur % N_target == 0:
        f = N_cur // N_target
        return h[:f * N_target].reshape(N_target, f).mean(axis=1)
    x_old = np.linspace(0, 1, N_cur, endpoint=False)
    x_new = np.linspace(0, 1, N_target, endpoint=False)
    return np.interp(x_new, x_old, h)


def _exact_downsample_check(h):
    best_h = h.copy()
    best_C = _C(h)
    n = len(h)
    f = 2
    while f <= 8 and n % f == 0:
        hd = h.reshape(n // f, f).mean(axis=1)
        Cd = _C(hd)
        if Cd < best_C:
            best_C = Cd
            best_h = hd
        f *= 2
    return best_h, best_C


def _local_symmetrize(h, half_win=None):
    """Exploit near-symmetry: average h[i] with h[N-1-i] (autoconvolution
    of symmetric h is symmetric; the max sits near center)."""
    N = len(h)
    return 0.5 * (h + h[::-1])


def construct(budget_seconds, start):
    t0 = time.process_time()
    margin = 1.5
    deadline = budget_seconds - margin

    if start is not None:
        h_start = np.asarray(start, dtype=float)
        if h_start.sum() <= 0 or not np.all(np.isfinite(h_start)):
            h_start = None
    else:
        h_start = None

    if h_start is None:
        N = 400
        x = np.linspace(-0.25, 0.25, N, endpoint=False) + 0.25 / N
        h_start = np.exp(-2.6 * (x - x.min()))

    h_start = np.maximum(h_start, 1e-12)
    best_h, best_C = _exact_downsample_check(h_start)

    # KEY NEW MOVE: enforce symmetry (h[i] = h[N-1-i]) on a symmetrized copy.
    # For symmetric input the autoconvolution is symmetric and its max sits
    # at the center; the optimizer works in the half-space with an even
    # extension. This halves the parameter count and removes a whole family
    # of near-degenerate directions.
    N_final = 30000
    h_sym = _local_symmetrize(np.maximum(_upsample(best_h, N_final), 1e-12))
    Cs = _C_fft(h_sym)
    if Cs < best_C:
        best_C = Cs
        best_h = h_sym
    print("symmetrized C=%.6f t=%.2f" % (Cs, time.process_time() - t0))

    # Optimise the symmetric half using a full-length parametrisation but
    # symmetrising the gradient so the iterates stay symmetric.
    half = N_final // 2
    z_sym = np.log(np.maximum(h_sym, 1e-12))

    def _sym_grad(g):
        return 0.5 * (g + g[::-1])

    def fun_sym(z):
        C, g = _softmax_C_and_grad(z, 1.0)
        return C, _sym_grad(g)

    def fun_sym_beta(beta):
        def f(z):
            C, g = _softmax_C_and_grad(z, beta)
            return C, _sym_grad(g)
        return f

    def fun_hard_sym(z):
        N = len(z)
        h = np.exp(np.clip(z, -20, 20))
        S = h.sum()
        if S <= 0:
            return 1e9, np.zeros(N)
        conv = fftconvolve(h, h, 'full')
        m = conv.max()
        C = 2.0 * N * m / (S * S)
        tol = 1e-6 * max(1.0, abs(m))
        active = np.where(conv >= m - tol)[0]
        mask = np.zeros(N + N - 1)
        mask[active] = 1.0
        na = float(len(active))
        corr = fftconvolve(mask, h[::-1], 'full')[N - 1:2 * N - 1]
        g_h = -2.0 * C / S + (4.0 * N / (S * S)) * (1.0 / na) * corr
        g = h * g_h
        return C, _sym_grad(g)

    def _run(fun, z0, maxiter, dl):
        def cb(xk):
            return time.process_time() - t0 > dl
        try:
            res = minimize(fun, z0, jac=True, method='L-BFGS-B',
                           bounds=[(-20.0, 20.0)] * len(z0),
                           callback=cb,
                           options={'maxiter': maxiter, 'ftol': 1e-16,
                                    'gtol': 1e-14, 'maxcor': 40})
            return res.x
        except Exception:
            return z0

    # Multi-beta schedule on full-length symmetric parametrisation.
    for beta in (300.0, 1200.0, 5000.0, 20000.0, 80000.0):
        if time.process_time() > deadline - 3.0:
            break
        z_sym = _run(fun_sym_beta(beta), z_sym, 300, deadline - 2.5)
        h = np.exp(np.clip(z_sym, -20, 20))
        h = _local_symmetrize(h)
        C = _C_fft(h)
        if C < best_C:
            best_C = C
            best_h = h
        print("soft beta=%.0f C=%.6f t=%.2f" %
              (beta, C, time.process_time() - t0))

    # Hard polish, symmetric.
    if time.process_time() < deadline - 1.0:
        z_sym = _run(fun_hard_sym, z_sym, 3000, deadline - 0.6)
        h = _local_symmetrize(np.exp(np.clip(z_sym, -20, 20)))
        C = _C_fft(h)
        if C < best_C:
            best_C = C
            best_h = h
        print("hard sym C=%.6f t=%.2f" % (C, time.process_time() - t0))

    # Final refinement: strict-tolerance hard polish on the symmetric result.
    if time.process_time() < deadline - 0.4:
        z_sym = _run(fun_hard_sym, np.log(np.maximum(best_h, 1e-12)),
                     2000, deadline - 0.2)
        h = _local_symmetrize(np.exp(np.clip(z_sym, -20, 20)))
        C = _C_fft(h)
        if C < best_C:
            best_C = C
            best_h = h

    hn, Cn = _exact_downsample_check(best_h)
    if Cn < best_C:
        best_C = Cn
        best_h = hn

    print("final C = %.9f  N=%d  t=%.2f" % (best_C, len(best_h),
                                            time.process_time() - t0))
    return best_h

