        h = np.exp(np.clip(z, -20, 20))
        hd, Cd = _exact_downsample_check(h)
        if Cd < best_C:
            best_C = Cd
            best_h = hd

    # Iterated active-set reidentification with tight least-squares solve.
    for it in range(6):
        if time.process_time() > deadline - 1.5:
